class Solution {
  public int remainderBoxesPositiveInkInvoice(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]boxes=new int[5];for(int x:a)boxes[Math.floorMod(x,5)]++;for(int x:boxes)out.add(x);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
